# ================================================================ 4.1.1–4.1.3
L(
    id="az305-compute", title="Design compute: workload requirements, VMs and containers", objectives=["AZ305-4.1.1", "AZ305-4.1.2", "AZ305-4.1.3"], minutes=50,
    objective="Specify compute components from workload requirements, and recommend VM-based and container-based solutions.",
    prereqs=[("Creating VMs (AZ-104)", "AZ104-3.2.1", "az104-vm-create"), ("Containers (AZ-104)", "AZ104-3.3.2", "az104-containers")],
    foundation=[
        "Choose compute by asking how much control you need. The less you manage, the more time you spend on the app.",
        "From least to most control: serverless functions, App Service, Container Apps, Kubernetes (AKS), virtual machines.",
        "Then size it, decide how it scales, and pick the cheapest pricing that still fits.",
    ],
    engineer=[
        "Requirements to components: hosting model (code or container), OS and runtime needs, scale pattern (steady, bursty, event-driven, scale to zero), state, network isolation (VNet integration, private endpoints), availability (zones, regions), compliance (dedicated hosts, confidential computing), and cost model. The Azure compute decision tree in the Architecture Center starts from lift-and-shift versus cloud-optimised.",
        "VM-based: size families (B burstable, D general purpose, E memory, F compute, L storage, M large memory, N GPU, H HPC), Trusted Launch and confidential VMs, managed disk types, Virtual Machine Scale Sets (Flexible) for scale-out, availability zones, proximity placement groups for latency, Azure Dedicated Host for single-tenant physical servers, Spot VMs for interruptible work, reservations or savings plans and Azure Hybrid Benefit for steady workloads, Azure Virtual Desktop for desktops and apps, and Azure VMware Solution to run VMware workloads natively.",
        "Container-based: Azure Container Apps (serverless microservices, KEDA scaling to zero, revisions, Dapr, jobs), AKS (full Kubernetes API, node pools, operators, service mesh; AKS Automatic simplifies operations), Azure Container Instances (single container groups on demand), App Service for containers (web apps in containers), Azure Container Registry (Premium for geo-replication and private endpoints).",
    ],
    anim=("az305-compute-sim", "Pick the compute service, then the VM pricing and placement option."),
    example=("Choosing compute for a logistics platform", [
        "The customer portal runs on App Service; ten microservices run on Container Apps scaling on queue length; the routing engine with custom operators runs on AKS.",
        "A legacy Windows app moves as-is to VMs in a zone-spread scale set with reservations; nightly re-optimisation jobs use Spot VMs; dispatchers get Azure Virtual Desktop.",
    ]),
    config=cfg(["Create a resource: App Service / Container Apps / Kubernetes service / Virtual machine.", "VM > Size, Availability options (zones, scale set), Spot discount.", "Reservations > Purchase; Advisor cost recommendations."],
               cli="az containerapp create -g rg-app -n orders --environment cae-prod --image acrcontoso.azurecr.io/orders:1.0 --min-replicas 0 --max-replicas 30\naz vm create -g rg-batch -n vm-spot01 --image Ubuntu2204 --size Standard_D4s_v5 --priority Spot --eviction-policy Deallocate --max-price -1",
               ps="New-AzContainerApp -ResourceGroupName rg-app -Name orders -EnvironmentId $env.Id -Location westeurope"),
    lab=lab("Match each workload to compute and VM options.", [("compute", "compute service"), ("vm-choice", "VM option")], ["Answer every case in both trainers."],
            ["Most managed service that meets requirements", "Spot for interruptible, reservations for steady"], ["Defaulting to VMs for web apps", "Running AKS for a few simple containers"]),
    troubleshooting=[("Spot VM workloads stop unexpectedly.", "Azure evicted the Spot VMs for capacity.", "Use Spot only for interruptible work and checkpoint progress."),
                     ("Small team overwhelmed by AKS upgrades and node management.", "More control than needed.", "Consider Container Apps or AKS Automatic.")],
    comparisons=[("Container Apps vs AKS", "Container Apps: serverless, no cluster to manage; AKS: full Kubernetes control."), ("Reservations vs Spot", "Reservations: committed steady use at a discount; Spot: spare capacity, evictable, deepest discount.")],
    misconceptions=[("Containers always need Kubernetes.", "Container Apps and ACI run containers without managing a cluster."), ("VMs are the default for migration.", "They are the fastest path, but PaaS reduces long-term operations.")],
    decisions=["Start at the most managed compute and move down only for a reason.", "Right-size VMs and use reservations/Hybrid Benefit for steady use.", "Container Apps for microservices; AKS when you need Kubernetes itself."],
    docs=[("Choose an Azure compute service", TC + "compute-decision-tree"), ("Choose an Azure container service", AAC + "guide/choose-azure-container-service"), ("Azure Spot VMs", ML + "azure/virtual-machines/spot-vms"), ("Virtual machine sizes", ML + "azure/virtual-machines/sizes/overview"), ("Azure Container Apps overview", ML + "azure/container-apps/overview")],
    walk_=("Run each workload on the most managed compute that meets its needs, at the right size and price.",
           ["From requirements to compute", "VM-based solutions: size, scale, price", "Container-based solutions"],
           row(0, ("req", "Workload needs", "user", "control, scale, cost"), ("fn", "Functions", "compute"), ("as", "App Service", "compute"))
           + row(1, ("aca", "Container Apps", "compute"), ("aks", "AKS", "compute"), ("vm", "Virtual machines", "compute"))
           + row(2, ("spot", "Spot", "cost", "interruptible"), ("ri", "Reservations", "cost", "steady 24/7"), ("vmss", "Scale sets", "service", "scale out")),
           [S("problem", "Problem", "Many workloads, many compute options", "Web apps, microservices, a legacy Windows app and nightly batch jobs all need somewhere to run.", add=["req"]),
            S("concept", "Ladder", "Less to manage at the top", "Functions and App Service: you bring code. Container Apps: you bring containers, Azure runs them. AKS: you run Kubernetes. VMs: you run everything.", add=["fn", "as", "aca", "aks", "vm"], edges=[("req", "fn"), ("req", "as"), ("req", "aca")], learn=[0], tip="Move down the ladder only when a requirement forces you to."),
            S("technique", "VMs", "Size, scale, pay less", "Pick the size family by CPU, memory, GPU or storage needs. Scale sets add VMs with load. Spot VMs for work that can be interrupted; reservations or savings plans for VMs that run all the time.", add=["spot", "ri", "vmss"], edges=[("vm", "vmss"), ("vm", "spot"), ("vm", "ri")], learn=[1]),
            S("technique", "Containers", "Container Apps or AKS", "Container Apps runs microservices without a cluster and scales to zero. AKS gives full Kubernetes when you need operators, custom networking or node control.", focus=["aca", "aks"], learn=[2]),
            S("recap", "Recap", "Compute design", "Least management that meets the need.", recap=["Functions → App Service → Container Apps → AKS → VMs", "VM family, scale sets, Spot, reservations", "Container Apps for microservices; AKS for Kubernetes control"])]),
)
qa("AZ305-4.1.1", 2, "scenario", "A team must host a Java web API with deployment slots, custom domains and autoscale, and wants minimal operations. Which compute?", [("Azure App Service", "Correct."), ("AKS", "More operations than needed."), ("Virtual machines", "Most operations."), ("Azure Batch", "For parallel jobs.")], "a", "App Service is the managed web platform with slots and domains.", TC + "compute-decision-tree")
