qa("AZ305-4.1.2", 3, "scenario", "Call-centre staff need a managed Windows desktop with company apps from home on personal devices. What do you recommend?", [("Azure Virtual Desktop", "Correct."), ("One VM per user with RDP from the internet", "Insecure and unmanaged."), ("Azure Bastion", "Admin access to VMs, not user desktops."), ("App Service", "Web apps only.")], "a", "Azure Virtual Desktop delivers desktops and apps to any device.", ML + "azure/virtual-desktop/overview")
qa("AZ305-4.1.3", 2, "scenario", "Twelve microservices must scale on HTTP traffic and Service Bus queue length, including to zero. The team doesn't want to manage a cluster. What do you recommend?", [("Azure Container Apps", "Correct."), ("AKS", "Requires cluster management."), ("Azure Container Instances", "No built-in autoscale or service discovery."), ("VM Scale Sets", "Not container-native.")], "a", "Container Apps runs microservices with KEDA scaling and no cluster to manage.", ML + "azure/container-apps/overview")
qa("AZ305-4.1.3", 2, "scenario", "The platform team needs Kubernetes custom resource definitions, operators and a service mesh. What do you recommend?", [("Azure Kubernetes Service", "Correct."), ("Container Apps", "Doesn't expose the Kubernetes API."), ("ACI", "No orchestration."), ("App Service", "Not Kubernetes.")], "a", "AKS provides the full Kubernetes API.", ML + "azure/aks/what-is-aks")
qa("AZ305-4.1.3", 2, "scenario", "Container images must be stored once and pulled from registries in three regions over private endpoints. Which registry design?", [("Azure Container Registry Premium with geo-replication and private endpoints", "Correct."), ("ACR Basic in one region", "No geo-replication or private endpoints."), ("Docker Hub public repository", "Not private."), ("Blob storage", "Not a registry.")], "a", "Geo-replication and private link require the Premium tier.", ML + "azure/container-registry/container-registry-geo-replication")

# ================================================================ 4.1.4–4.1.5
L(
    id="az305-serverless-batch", title="Design serverless and batch compute", objectives=["AZ305-4.1.4", "AZ305-4.1.5"], minutes=35,
    objective="Recommend serverless solutions (Functions, Durable Functions, Logic Apps, Container Apps) and batch processing solutions (Azure Batch, Container Apps jobs, Spot capacity).",
    prereqs=[("Compute design", "AZ305-4.1.1", "az305-compute")],
    foundation=[
        "Serverless means you write code or a workflow and Azure runs it only when something happens. You pay for what runs.",
        "Batch processing means running lots of work in parallel, such as thousands of simulations overnight.",
    ],
    engineer=[
        "Azure Functions: event-driven code (HTTP, timers, queues, Event Grid, Event Hubs, Cosmos DB change feed). Hosting: Flex Consumption (recommended serverless plan: fast scale, scale to zero, VNet integration, always-ready instances), Premium (pre-warmed instances, longer runs), Dedicated (App Service plan). Durable Functions add stateful orchestration: function chaining, fan-out/fan-in, async HTTP APIs, monitors and human interaction.",
        "Azure Logic Apps: low-code workflows with hundreds of managed connectors (Microsoft 365, SAP, Salesforce), Consumption (multi-tenant, pay per action) or Standard (single-tenant, VNet integration, stateful and stateless workflows). Good for integration owned by citizen developers or integration teams.",
        "Batch: Azure Batch schedules large parallel and HPC workloads on pools of VMs (including Spot/low-priority nodes and GPU or HPC sizes) with job and task management and auto-scaling formulas; Container Apps jobs run containerised tasks on demand, on a schedule or triggered by events; HPC options include H-series VMs with InfiniBand and Azure Managed Lustre storage.",
    ],
    anim=("az305-serverless-sim", "Choose Functions, Durable Functions, Logic Apps, Batch or Container Apps jobs."),
    example=("An insurance claims pipeline", [
        "Uploaded claim photos trigger a function that resizes and classifies them. A Durable Functions orchestration waits for an assessor's approval, then pays out.",
        "A Logic App posts approved claims to Teams and the finance SAP system. Monthly risk simulations run on Azure Batch with Spot nodes.",
    ]),
    config=cfg(["Function App > Create: hosting plan (Flex Consumption / Premium / Dedicated).", "Logic App > Create: Consumption or Standard.", "Batch account > Pools: VM size, Spot nodes, autoscale formula."],
               cli="az functionapp create -g rg-app -n func-claims --storage-account stclaims --flexconsumption-location westeurope --runtime dotnet-isolated --runtime-version 8.0\naz batch pool create --id pool-sim --vm-size Standard_D4s_v5 --target-low-priority-nodes 50 --image canonical:0001-com-ubuntu-server-jammy:22_04-lts --node-agent-sku-id \"batch.node.ubuntu 22.04\"",
               ps="New-AzFunctionApp -ResourceGroupName rg-app -Name func-claims -StorageAccountName stclaims -Runtime DotNet -FunctionsVersion 4 -Location westeurope"),
    lab=lab("Pick the serverless or batch service.", [("serverless", "serverless or batch service")], ["Answer every case."], ["Durable Functions for long-running stateful flows", "Batch for massive parallel work"], ["Using a timer loop in a function to wait for approval", "Running HPC jobs on one big VM"]),
    troubleshooting=[("A function times out waiting for an external approval.", "Functions are short-lived and stateless.", "Use a Durable Functions orchestration with an external event."),
                     ("Batch jobs take too long to start each night.", "Pool scales from zero.", "Use an autoscale formula that pre-provisions before the job window.")],
    comparisons=[("Functions vs Logic Apps", "Functions: code-first; Logic Apps: designer-first with connectors."), ("Azure Batch vs Container Apps jobs", "Batch: large VM pools and HPC scheduling; Container Apps jobs: containerised tasks without managing pools.")],
    misconceptions=[("Serverless means no limits.", "Plans have execution, scale and memory limits."), ("Logic Apps can't run in a VNet.", "Logic Apps Standard supports VNet integration.")],
    decisions=["Flex Consumption Functions for event-driven code.", "Durable Functions for stateful orchestration.", "Batch (with Spot) for large parallel jobs."],
    docs=[("Azure Functions overview", ML + "azure/azure-functions/functions-overview"), ("Flex Consumption plan", ML + "azure/azure-functions/flex-consumption-plan"), ("Durable Functions", ML + "azure/azure-functions/durable/durable-functions-overview"), ("What is Azure Logic Apps?", ML + "azure/logic-apps/logic-apps-overview"), ("What is Azure Batch?", ML + "azure/batch/batch-technical-overview")],
    walk_=("Run code only when something happens, and run huge parallel jobs without managing servers.",
           ["Functions and Flex Consumption", "Durable Functions and Logic Apps", "Batch processing"],
           row(0, ("ev", "Event", "user", "blob, queue, HTTP"), ("fn", "Azure Functions", "compute", "event-driven"), ("df", "Durable Functions", "compute", "stateful"))
           + row(1, ("la", "Logic Apps", "service", "connectors"), ("ext", "SAP, Teams, Salesforce", "service"))
           + row(2, ("batch", "Azure Batch", "compute", "VM pools"), ("spot", "Spot nodes", "cost")),
           [S("problem", "Problem", "Work that comes and goes", "Photos arrive at random, approvals take days, and simulations need 1,000 cores once a month.", add=["ev"]),
            S("concept", "Functions", "Code that runs on events", "A function wakes up for each event and scales out with load. The Flex Consumption plan scales fast, can scale to zero, and supports VNet integration.", add=["fn"], edges=[("ev", "fn")], learn=[0]),
            S("technique", "Workflows", "State and integration", "Durable Functions remember where they are, so an order can wait days for approval. Logic Apps build workflows in a designer with hundreds of connectors.", add=["df", "la", "ext"], edges=[("fn", "df"), ("df", "la"), ("la", "ext")], learn=[1]),
            S("technique", "Batch", "Thousands of tasks in parallel", "Azure Batch creates a pool of VMs, runs the tasks and scales the pool away. Spot nodes cut cost for work that can be retried.", add=["batch", "spot"], edges=[("batch", "spot")], learn=[2]),
            S("recap", "Recap", "Serverless and batch", "Pay for work done.", recap=["Functions (Flex Consumption) for events", "Durable Functions for state; Logic Apps for connectors", "Batch + Spot for parallel jobs"])]),
)
qa("AZ305-4.1.4", 2, "scenario", "Every image uploaded to a container must be resized within seconds. Volume varies from zero to thousands per minute. What do you recommend?", [("An Azure Function triggered by Event Grid blob events on the Flex Consumption plan", "Correct."), ("A VM polling the container every minute", "Wasteful and slow."), ("Azure Batch", "For large batch jobs."), ("A Logic App Standard with a timer", "Polling, not event-driven.")], "a", "Event-driven functions scale automatically and cost nothing when idle.", ML + "azure/azure-functions/flex-consumption-plan")
qa("AZ305-4.1.4", 2, "scenario", "An order workflow must call three services in sequence, wait up to 5 days for a manager's approval, and resume. What do you recommend?", [("Durable Functions orchestration", "Correct."), ("A single function with a sleep loop", "Exceeds timeouts and wastes compute."), ("Azure Batch", "Not for workflows."), ("Event Hubs", "Streaming ingestion.")], "a", "Durable orchestrations keep state and wait for external events.", ML + "azure/azure-functions/durable/durable-functions-overview")
qa("AZ305-4.1.4", 2, "scenario", "Business analysts must build a workflow that saves email attachments to SharePoint and creates a Salesforce record, with little code. What do you recommend?", [("Azure Logic Apps", "Correct."), ("Azure Functions", "Code-first."), ("AKS", "Overkill."), ("Azure Batch", "Parallel jobs.")], "a", "Logic Apps provides managed connectors and a designer.", ML + "azure/logic-apps/logic-apps-overview")
qa("AZ305-4.1.5", 2, "scenario", "A bank runs 20,000 independent risk simulations each night on hundreds of cores, and wants the lowest cost. What do you recommend?", [("Azure Batch with Spot (low-priority) nodes", "Correct."), ("One very large VM", "Slow and a single point of failure."), ("Azure Functions Consumption", "Not for long CPU-heavy jobs at this scale."), ("App Service WebJobs", "Not designed for HPC.")], "a", "Batch schedules parallel tasks across pools and supports Spot nodes.", ML + "azure/batch/batch-technical-overview")
qa("AZ305-4.1.5", 2, "scenario", "A containerised data-cleanup task must run every night for 20 minutes without managing VM pools. What do you recommend?", [("Azure Container Apps jobs (scheduled)", "Correct."), ("Azure Batch with a dedicated pool", "Pool management."), ("An always-on VM with cron", "Pays 24/7."), ("Event Grid", "Event routing.")], "a", "Container Apps jobs run containers on a schedule and stop when done.", ML + "azure/container-apps/jobs")
qa("AZ305-4.1.5", 3, "scenario", "Tightly coupled CFD simulations need low-latency interconnect between nodes and a fast parallel file system. What do you recommend?", [("HPC VM sizes with InfiniBand in a Batch or CycleCloud cluster, with Azure Managed Lustre", "Correct."), ("Spot B-series VMs", "Burstable, no InfiniBand."), ("Azure Functions", "Not for MPI workloads."), ("Blob Storage Archive", "Offline storage.")], "a", "HPC series VMs with RDMA/InfiniBand and a parallel file system suit tightly coupled MPI jobs.", ML + "azure/high-performance-computing/")

# ================================================================ 4.2.1–4.2.3
L(
    id="az305-messaging-events", title="Design messaging, event-driven and API architectures", objectives=["AZ305-4.2.1", "AZ305-4.2.2", "AZ305-4.2.3"], minutes=45,
    objective="Recommend a messaging architecture, an event-driven architecture and an API integration solution.",
    prereqs=[("Serverless and batch compute", "AZ305-4.1.4", "az305-serverless-batch")],
    foundation=[
        "Parts of an app talk in two ways. A message is a request someone must handle (process this order). An event is news that something happened (a file was uploaded).",
        "Queues and Service Bus carry messages; Event Grid and Event Hubs carry events. API Management puts a safe, managed front door on your APIs.",
    ],
    engineer=[
        "Messaging: Azure Queue Storage (simple, very large queues over 80 GB, at-least-once delivery, no ordering guarantees) and Azure Service Bus (enterprise broker: queues and topics with subscriptions and filters, FIFO through sessions, duplicate detection, dead-lettering, transactions, scheduled messages; Premium tier for VNet isolation, predictable performance and messages up to 100 MB). Patterns: competing consumers, queue-based load levelling, publish-subscribe.",
        "Events: Event Grid (discrete events, push delivery to handlers, filtering, retries and dead-lettering; system topics for Azure resources, custom topics, namespaces with MQTT); Event Hubs (high-throughput event streaming with partitions, consumer groups, retention, Capture to storage and a Kafka endpoint). Event-driven styles: simple event processing (Event Grid → Function), stream processing (Event Hubs → Stream Analytics/Databricks), event sourcing.",
        "APIs: Azure API Management (gateway with policies for authentication, rate limiting, caching and transformation; products and subscriptions; versions and revisions; developer portal; tiers from Consumption to Premium v2, with self-hosted gateways for hybrid). Combine with Application Gateway or Front Door for WAF, and private endpoints or VNet injection for internal APIs.",
    ],
    anim=("az305-messaging-sim", "Choose the messaging or eventing service for each requirement."),
    example=("Order processing at an online retailer", [
        "Orders go onto a Service Bus topic; billing, shipping and email services each have a subscription with filters, and sessions keep each customer's orders in sequence.",
        "Storage uploads raise Event Grid events to functions; clickstream data flows through Event Hubs to analytics; partners call order APIs through API Management with keys and rate limits.",
    ]),
    config=cfg(["Service Bus namespace > Topics > Subscriptions and filters; queue properties (sessions, duplicate detection).", "Event Grid > System topics / Event subscriptions.", "API Management > APIs, Products, Policies, Developer portal."],
               cli="az servicebus topic create -g rg-app --namespace-name sb-orders -n orders\naz servicebus topic subscription create -g rg-app --namespace-name sb-orders --topic-name orders -n billing\naz apim create -g rg-api -n apim-contoso --publisher-email api@contoso.com --publisher-name Contoso --sku-name StandardV2",
               ps="New-AzServiceBusTopic -ResourceGroupName rg-app -NamespaceName sb-orders -Name orders"),
    lab=lab("Pick the messaging or eventing service.", [("messaging", "messaging service")], ["Answer every case."], ["Service Bus for enterprise messaging; Event Grid for reactive events; Event Hubs for streams"], ["Using Event Grid for ordered commands", "Using Queue Storage when FIFO and duplicate detection are needed"]),
    troubleshooting=[("Messages are processed twice after retries.", "At-least-once delivery without idempotency.", "Make handlers idempotent and enable Service Bus duplicate detection."),
                     ("Partners overload the backend API.", "No throttling.", "Add API Management rate-limit and quota policies.")],
    comparisons=[("Service Bus vs Queue Storage", "Service Bus: FIFO, transactions, topics, dead-letter; Queue Storage: simple, cheap, huge queues."), ("Event Grid vs Event Hubs", "Event Grid: discrete events pushed to handlers; Event Hubs: high-volume streams read by consumers.")],
    misconceptions=[("Events and messages are the same.", "A message expects processing; an event announces a fact."), ("Event Hubs pushes events to subscribers.", "Consumers pull from partitions.")],
    decisions=["Messages → Service Bus (or Queue Storage when simple).", "Discrete events → Event Grid; streams → Event Hubs.", "Expose APIs through API Management."],
    docs=[("Compare messaging services", ML + "azure/event-grid/compare-messaging-services"), ("Storage queues vs Service Bus queues", ML + "azure/service-bus-messaging/service-bus-azure-and-storage-queues-compared-contrasted"), ("Event-driven architecture style", AAC + "guide/architecture-styles/event-driven"), ("API Management key concepts", ML + "azure/api-management/api-management-key-concepts")],
    walk_=("Let parts of an app talk reliably — with messages, events and well-managed APIs.",
           ["Messages: Queue Storage vs Service Bus", "Events: Event Grid vs Event Hubs", "APIs through API Management"],
           row(0, ("shop", "Web shop", "compute"), ("sb", "Service Bus topic", "service", "orders"), ("bill", "Billing", "compute"), ("ship", "Shipping", "compute"))
           + row(1, ("blob", "Storage", "storage"), ("eg", "Event Grid", "service", "push events"), ("fn", "Function", "compute"))
           + row(2, ("iot", "Devices", "compute"), ("eh", "Event Hubs", "service", "stream"), ("apim", "API Management", "network", "partners")),
           [S("problem", "Problem", "Parts that must talk", "Orders must reach billing and shipping, uploads must trigger processing, devices stream telemetry, and partners call APIs.", add=["shop"]),
            S("concept", "Messages", "Commands that must be handled", "Service Bus: queues and topics with ordering (sessions), duplicate detection and dead-lettering. Topics let each service subscribe with filters. Queue Storage is simpler and cheaper.", add=["sb", "bill", "ship"], edges=[("shop", "sb"), ("sb", "bill"), ("sb", "ship")], learn=[0]),
            S("concept", "Events", "News that something happened", "Event Grid pushes discrete events (a blob was created) to handlers. Event Hubs ingests millions of events per second as a stream for analytics.", add=["blob", "eg", "fn", "iot", "eh"], edges=[("blob", "eg"), ("eg", "fn"), ("iot", "eh")], learn=[1]),
            S("technique", "APIs", "A managed front door for APIs", "API Management adds keys, rate limits, versions, transformation and a developer portal in front of your services.", add=["apim"], edges=[("apim", "shop")], learn=[2]),
            S("recap", "Recap", "App communication", "Message, event or API?", recap=["Service Bus (FIFO, topics) vs Queue Storage (simple)", "Event Grid (discrete) vs Event Hubs (stream)", "API Management for APIs"])]),
)
qa("AZ305-4.2.1", 2, "scenario", "Payments must be processed in order per customer, duplicates must be discarded, and failed messages kept for inspection. What do you recommend?", [("Service Bus queue with sessions, duplicate detection and dead-lettering", "Correct."), ("Queue Storage", "No ordering or duplicate detection."), ("Event Grid", "Event routing, no FIFO."), ("Event Hubs", "Streaming, not command processing.")], "a", "Service Bus provides FIFO sessions, duplicate detection and dead-letter queues.", ML + "azure/service-bus-messaging/service-bus-azure-and-storage-queues-compared-contrasted")
qa("AZ305-4.2.1", 2, "scenario", "One order message must reach billing, shipping and analytics, and each service only wants certain order types. What do you recommend?", [("A Service Bus topic with filtered subscriptions", "Correct."), ("Three separate queues written by the sender", "Couples the sender to every consumer."), ("Queue Storage", "No publish-subscribe."), ("A shared database table", "Not messaging.")], "a", "Topics and subscriptions implement publish-subscribe with filters.", ML + "azure/service-bus-messaging/service-bus-queues-topics-subscriptions")
qa("AZ305-4.2.1", 2, "single", "When should you choose Azure Queue Storage over Service Bus queues?", [("When you need a simple queue that can grow beyond 80 GB and don't need FIFO or transactions", "Correct."), ("When you need ordered delivery", "Service Bus."), ("When you need topics", "Service Bus."), ("When you need duplicate detection", "Service Bus.")], "a", "Queue Storage is simple and very large; Service Bus adds enterprise features.", ML + "azure/service-bus-messaging/service-bus-azure-and-storage-queues-compared-contrasted")
qa("AZ305-4.2.2", 2, "scenario", "Whenever a resource is created in any subscription, a function must check its tags within seconds. What do you recommend?", [("Event Grid system topic subscription for resource events", "Correct."), ("Event Hubs", "Streaming platform."), ("A timer function scanning every hour", "Slow."), ("Service Bus queue", "Azure doesn't post resource events there.")], "a", "Event Grid delivers Azure resource events to handlers.", ML + "azure/event-grid/overview")
qa("AZ305-4.2.2", 2, "scenario", "Two million devices send telemetry every few seconds; several analytics apps must read the same stream independently. What do you recommend?", [("Event Hubs with consumer groups", "Correct."), ("Event Grid", "Discrete events, not high-volume streams."), ("Service Bus queue", "Not designed for this throughput."), ("Queue Storage", "One consumer pattern, lower throughput.")], "a", "Event Hubs partitions scale ingestion; consumer groups let apps read independently.", ML + "azure/event-hubs/event-hubs-about")
qa("AZ305-4.2.2", 3, "scenario", "An existing Kafka-based producer must send to Azure without code changes, and data must also land in a data lake automatically. What do you recommend?", [("Event Hubs with the Kafka endpoint and Capture", "Correct."), ("Event Grid", "No Kafka protocol."), ("Service Bus Premium", "No Kafka endpoint."), ("IoT Hub only", "Device scenarios.")], "a", "Event Hubs supports the Kafka protocol and Capture to storage.", ML + "azure/event-hubs/azure-event-hubs-apache-kafka-overview")
qa("AZ305-4.2.3", 2, "scenario", "Internal APIs must be published to partners with subscription keys, per-partner quotas, versioning and self-service documentation. What do you recommend?", [("Azure API Management", "Correct."), ("Application Gateway", "Layer 7 routing, no developer portal or products."), ("Front Door", "Global edge, not API productisation."), ("Event Grid", "Events.")], "a", "API Management provides products, policies, versions and a developer portal.", ML + "azure/api-management/api-management-key-concepts")
qa("AZ305-4.2.3", 2, "scenario", "APIs run in two on-premises datacenters and Azure. They must share one set of policies and a single control plane. What do you recommend?", [("API Management with self-hosted gateways on-premises", "Correct."), ("Separate API gateways per site", "No central management."), ("Application proxy", "Publishes web apps, not API products."), ("Traffic Manager", "DNS routing only.")], "a", "Self-hosted gateways run API Management policies close to on-premises APIs.", ML + "azure/api-management/self-hosted-gateway-overview")
qa("AZ305-4.2.3", 3, "configuration", "Partners must be limited to 1,000 calls per hour each without changing backend code. Where do you implement it?", [("A rate-limit/quota policy in API Management", "Correct."), ("In each backend service", "Requires code changes."), ("An NSG rule", "Layer 4 only."), ("Azure Policy", "Not runtime traffic.")], "a", "API Management policies enforce rate limits and quotas per subscription.", ML + "azure/api-management/api-management-policies")

# ================================================================ 4.2.4–4.2.6
L(
    id="az305-app-platform", title="Design caching, configuration and automated deployment", objectives=["AZ305-4.2.4", "AZ305-4.2.5", "AZ305-4.2.6"], minutes=40,
    objective="Recommend a caching solution, an application configuration management solution, and an automated deployment solution for applications.",
    prereqs=[("Deployment slots (AZ-104)", "AZ104-3.4.8", "az104-app-service-ops"), ("ARM templates and Bicep (AZ-104)", "AZ104-3.1.1", "az104-arm-bicep")],
    foundation=[
        "Caching keeps frequently used data close and fast, so the database does less work.",
        "Configuration management keeps settings and feature flags in one place, outside the code.",
        "Automated deployment builds and releases the app the same way every time, with infrastructure described as code.",
    ],
    engineer=[
        "Caching: Azure Managed Redis (the successor to Azure Cache for Redis, which is being retired) for distributed cache, session state, rate limiting and pub/sub, with patterns such as cache-aside and TTL-based expiry; edge caching with Azure Front Door for static and cacheable content; API Management response caching; Cosmos DB integrated cache; in-memory caches in the app for per-instance data.",
        "Configuration: Azure App Configuration for central key-values, labels per environment, feature flags (with filters such as percentage rollout) and dynamic refresh; Key Vault for secrets (App Configuration stores Key Vault references); managed identities to read both; App Service and Functions settings with Key Vault references for simple apps.",
        "Automated deployment: infrastructure as code (Bicep or Terraform; template specs and deployment stacks for governed reuse); CI/CD with GitHub Actions or Azure Pipelines using workload identity federation; deployment strategies: deployment slots with swap (App Service), revisions with traffic splitting (Container Apps), blue-green and canary on AKS; environments with approvals; Azure Deployment Environments for developer self-service.",
    ],
    anim=("az305-app-config-sim", "Choose API Management, caching, configuration and the deployment approach."),
    example=("Shipping faster and safer", [
        "Product lookups use cache-aside with Azure Managed Redis; images are cached at the edge by Front Door. Settings live in App Configuration with labels per environment; secrets stay in Key Vault.",
        "GitHub Actions deploys Bicep and code on every merge using workload identity federation; new versions go to a staging slot, are warmed up and swapped; a feature flag enables the new checkout for 10% of users.",
    ]),
    config=cfg(["App Configuration > Configuration explorer, Feature manager.", "Azure Managed Redis: create cache, choose tier and size.", "App Service > Deployment slots; Deployment Center (GitHub Actions)."],
               cli="az appconfig create -g rg-app -n appcs-shop -l westeurope --sku Standard\naz appconfig feature set -n appcs-shop --feature new-checkout\naz webapp deployment slot swap -g rg-app -n app-shop --slot staging --target-slot production",
               ps="New-AzAppConfigurationStore -ResourceGroupName rg-app -Name appcs-shop -Location westeurope -Sku Standard"),
    lab=lab("Choose caching, configuration and deployment options.", [("api-cache", "API, cache or configuration service"), ("deployment", "deployment approach")], ["Answer every case in both trainers."],
            ["Redis for hot data; App Configuration for settings and flags", "IaC + CI/CD + slots for safe releases"], ["Putting secrets in App Configuration values", "Deploying straight to production with no slot"]),
    troubleshooting=[("Users see stale prices after updates.", "Cache entries never expire or aren't invalidated.", "Set a TTL and invalidate on write (cache-aside)."),
                     ("Changing a setting requires redeploying 20 services.", "Settings baked into each app.", "Move them to App Configuration with dynamic refresh.")],
    comparisons=[("App Configuration vs Key Vault", "App Configuration for settings and feature flags; Key Vault for secrets, keys and certificates."), ("Slots vs Container Apps revisions", "Both allow staged rollout; slots swap whole apps, revisions split traffic by percentage.")],
    misconceptions=[("A cache is a database.", "It holds copies that can disappear; the source of truth stays in the database."), ("CI/CD is only for code.", "Infrastructure should be deployed by the same pipelines as code.")],
    decisions=["Cache-aside with Azure Managed Redis; edge caching for static content.", "App Configuration + Key Vault references, read with managed identity.", "IaC + CI/CD with federated credentials; slots or revisions for safe rollout."],
    docs=[("What is Azure Managed Redis?", ML + "azure/redis/overview"), ("Cache-aside pattern", AAC + "patterns/cache-aside"), ("What is Azure App Configuration?", ML + "azure/azure-app-configuration/overview"), ("Deployment slots", ML + "azure/app-service/deploy-staging-slots"), ("Azure Deployment Environments", ML + "azure/deployment-environments/overview-what-is-azure-deployment-environments")],
    walk_=("Make the app fast with caching, easy to change with central configuration, and safe to release with automation.",
           ["Caching: Redis and edge caching", "Configuration: App Configuration and Key Vault", "Automated deployment: IaC, CI/CD, slots"],
           row(0, ("app", "Web app", "compute"), ("redis", "Azure Managed Redis", "database", "hot data"), ("db", "Database", "database"))
           + row(1, ("fd", "Front Door cache", "globe", "static files"), ("cfg", "App Configuration", "service", "settings + flags"), ("kv", "Key Vault", "security", "secrets"))
           + row(2, ("git", "GitHub Actions", "service", "CI/CD"), ("iac", "Bicep / Terraform", "service"), ("slot", "Staging slot", "compute", "swap")),
           [S("problem", "Problem", "Slow pages, scattered settings, risky releases", "The database is overloaded with the same reads, every service has its own settings file, and releases happen by hand on Friday nights.", add=["app", "db"], edges=[("app", "db")]),
            S("technique", "Cache", "Keep hot data close", "Cache-aside: check Redis first; on a miss, read the database and store the result with an expiry. Front Door caches static files near users.", add=["redis", "fd"], edges=[("app", "redis", "1st"), ("fd", "app")], learn=[0]),
            S("technique", "Config", "One place for settings", "App Configuration holds settings and feature flags for every service, per environment. Secrets stay in Key Vault and are referenced. Apps read both with their managed identity.", add=["cfg", "kv"], edges=[("app", "cfg"), ("cfg", "kv", "reference")], learn=[1]),
            S("technique", "Deploy", "Automate and release safely", "Bicep or Terraform describe the infrastructure; GitHub Actions or Azure Pipelines build and deploy on every merge; a staging slot is warmed up and swapped into production.", add=["git", "iac", "slot"], edges=[("git", "iac"), ("git", "slot"), ("slot", "app", "swap")], learn=[2]),
            S("recap", "Recap", "App platform design", "Fast, configurable, repeatable.", recap=["Cache-aside with Managed Redis; edge caching", "App Configuration + Key Vault references", "IaC + CI/CD + slots/revisions"])]),
)
qa("AZ305-4.2.4", 2, "scenario", "A product catalogue is read thousands of times per second but changes hourly. The database is overloaded. What do you recommend?", [("Cache-aside with Azure Managed Redis and a TTL", "Correct."), ("Scale the database to the largest size", "Expensive and doesn't remove repeated reads."), ("Store the catalogue in Archive tier", "Offline storage."), ("Add more web servers", "Load stays on the database.")], "a", "A distributed cache absorbs repeated reads; TTL keeps data fresh.", AAC + "patterns/cache-aside")
qa("AZ305-4.2.4", 2, "scenario", "A global site's images and scripts load slowly for users far from the origin region. What do you recommend?", [("Azure Front Door with caching", "Correct: content cached at edge locations."), ("Azure Managed Redis in the origin region", "Still far from users."), ("A bigger App Service plan", "Doesn't reduce distance."), ("ExpressRoute", "For private connectivity.")], "a", "Edge caching serves static content close to users.", ML + "azure/frontdoor/front-door-caching")
qa("AZ305-4.2.4", 2, "single", "Several web servers must share user session state so any server can handle the next request. What do you recommend?", [("A distributed cache such as Azure Managed Redis", "Correct."), ("In-process memory on each server", "Not shared."), ("Sticky sessions only", "Breaks when a server fails."), ("Table Storage Archive", "Not a tier.")], "a", "A shared cache lets any instance read session state.", ML + "azure/redis/overview")
qa("AZ305-4.2.5", 2, "scenario", "Thirty microservices share settings that change without redeployment, and a new feature must be turned on for 10% of users. What do you recommend?", [("Azure App Configuration with feature flags and dynamic refresh", "Correct."), ("Environment variables in each container", "Redeploy per change."), ("Key Vault secrets for every setting", "Meant for secrets."), ("A config file in Blob Storage", "No feature management.")], "a", "App Configuration centralises settings and feature flags with filters.", ML + "azure/azure-app-configuration/overview")
qa("AZ305-4.2.5", 2, "scenario", "Apps read settings from App Configuration. Database passwords must not be stored there. What do you recommend?", [("Store passwords in Key Vault and add Key Vault references in App Configuration", "Correct."), ("Encrypt the passwords and store them as values", "Still secrets in the wrong store."), ("Put passwords in code", "Never."), ("Use a separate App Configuration store for secrets", "App Configuration isn't a secret store.")], "a", "App Configuration references Key Vault so secrets stay in Key Vault.", ML + "azure/azure-app-configuration/use-key-vault-references-dotnet-core")
qa("AZ305-4.2.5", 3, "configuration", "Dev, test and prod must read different values for the same keys from one App Configuration store. What do you use?", [("Labels on key-values per environment", "Correct."), ("Three separate subscriptions", "Unnecessary for settings."), ("Feature flags", "For enabling features."), ("Tags on the store", "Metadata, not per-key values.")], "a", "Labels let the same key hold different values per environment.", ML + "azure/azure-app-configuration/concept-key-value")
qa("AZ305-4.2.6", 2, "scenario", "A web app must be released with zero downtime and instant rollback. What do you recommend?", [("Deploy to a staging slot, warm up, then swap", "Correct."), ("Stop the app, deploy, start", "Downtime."), ("Deploy to a new region each time", "Unnecessary."), ("Edit files in production", "Unsafe.")], "a", "Slot swap avoids downtime and can be reversed.", ML + "azure/app-service/deploy-staging-slots")
qa("AZ305-4.2.6", 2, "scenario", "Every environment must be created identically from source control, and changes reviewed by pull request. What do you recommend?", [("Infrastructure as code (Bicep or Terraform) deployed by CI/CD pipelines", "Correct."), ("Portal deployments documented in a wiki", "Not repeatable."), ("Exported templates edited by hand per environment", "Drift-prone."), ("Resource locks", "Don't deploy.")], "a", "IaC in Git with pipelines gives repeatable, reviewed deployments.", ML + "azure/azure-resource-manager/bicep/overview")
qa("AZ305-4.2.6", 3, "scenario", "Developers need to create short-lived environments from approved templates without raising tickets, with cost limits. What do you recommend?", [("Azure Deployment Environments", "Correct."), ("Owner on a shared subscription", "No guardrails."), ("Azure Blueprints", "Deprecated."), ("Manual requests to the platform team", "Tickets.")], "a", "Deployment Environments provides governed self-service from catalogs.", ML + "azure/deployment-environments/overview-what-is-azure-deployment-environments")
